export const printers=[
{id:'NY-M01',primary:true,name:'POPOMO · Midtown',area:'midtown',address:'Midtown Manhattan · W 34th St & Broadway',lat:40.7505,lng:-73.9882},
{id:'NY-M02',name:'POPOMO · Bryant Park',area:'midtown',address:'Midtown Manhattan · W 42nd St & 6th Ave',lat:40.7536,lng:-73.9832},
{id:'NY-S01',name:'POPOMO · SoHo',area:'soho',address:'SoHo · Broadway & Spring St',lat:40.7233,lng:-73.9981},
{id:'NY-L01',name:'POPOMO · Lower East Side',area:'soho',address:'Lower East Side · Delancey St & Essex St',lat:40.7184,lng:-73.9875},
{id:'NY-B01',name:'POPOMO · Williamsburg',area:'brooklyn',address:'Brooklyn · Bedford Ave & N 7th St',lat:40.7178,lng:-73.9576},
{id:'NY-B02',name:'POPOMO · Downtown Brooklyn',area:'brooklyn',address:'Brooklyn · Fulton St & Jay St',lat:40.6914,lng:-73.9874}];
export const areas=[{id:'midtown',name:'Midtown Manhattan',lat:40.7549,lng:-73.984},{id:'soho',name:'SoHo / Lower Manhattan',lat:40.7233,lng:-73.9981},{id:'brooklyn',name:'Brooklyn',lat:40.7081,lng:-73.9571}];
export function distance(a,b){const rad=d=>d*Math.PI/180,dlat=rad(b.lat-a.lat),dlng=rad(b.lng-a.lng),h=Math.sin(dlat/2)**2+Math.cos(rad(a.lat))*Math.cos(rad(b.lat))*Math.sin(dlng/2)**2;return 6371*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h));}
export function rankedPrinters(origin){return printers.map(p=>({...p,distance:distance(origin,p)})).sort((a,b)=>a.distance-b.distance);}
export const navigationURL=p=>'https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(p.lat+','+p.lng)+'&travelmode=walking&dir_action=navigate';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const en=()=>document.documentElement.lang.startsWith('en'),t=(zh,eng)=>en()?eng:zh;let currentOrigin=null;
export function getPrinter(id){return printers.find(p=>p.id===id);}
export function locationPrompt(){return new Promise(resolve=>{const d=document.createElement('dialog');d.className='location-prompt';d.setAttribute('aria-labelledby','location-title');d.innerHTML=`<span class="location-symbol" aria-hidden="true">⌖</span><h2 id="location-title">${t('找到离你最近的打印设备','Find your nearest printer')}</h2><p>${t('允许获取当前位置，将按直线距离排列纽约设备。你也可以手动选择区域。','Allow location access to sort New York printers by straight-line distance, or choose an area manually.')}</p><p class="location-status" role="status"></p><button class="primary" data-allow-location>${t('允许定位，查找附近设备','Use my location')}</button><button class="tertiary" data-manual-location>${t('手动选择纽约区域','Choose a New York area')}</button>`;document.body.append(d);let done=false;const finish=value=>{if(done)return;done=true;d.close();resolve(value);};d.querySelector('[data-manual-location]').onclick=()=>finish(null);d.querySelector('[data-allow-location]').onclick=()=>{const button=d.querySelector('[data-allow-location]'),status=d.querySelector('.location-status');if(!navigator.geolocation){status.textContent=t('此浏览器无法定位，请手动选择区域。','Location is unavailable. Choose an area manually.');return;}button.disabled=true;status.textContent=t('正在获取位置…','Finding your location…');navigator.geolocation.getCurrentPosition(pos=>{currentOrigin={lat:pos.coords.latitude,lng:pos.coords.longitude,kind:'current'};finish(currentOrigin);},err=>{button.disabled=false;status.textContent=t(err.code===1?'定位未授权，可以手动选择区域。':'暂时无法定位，请重试或手动选择区域。',err.code===1?'Location permission was denied. Choose an area manually.':'Location unavailable. Retry or choose an area.');},{enableHighAccuracy:false,timeout:10000,maximumAge:300000});};d.addEventListener('cancel',()=>{done=true;resolve(null);});d.addEventListener('close',()=>{d.remove();if(!done)resolve(null);},{once:true});d.showModal();});}
export function mountPrinterList(root,{onSelect,selectedId,origin=currentOrigin,limit=0}={}){let base=origin||{...areas[0],kind:'area'},search='';function render(){const matching=rankedPrinters(base).filter(p=>(p.name+' '+p.address+' '+p.id).toLowerCase().includes(search.toLowerCase()));const list=limit?matching.slice(0,limit):matching;root.innerHTML=`<div class="printer-location-bar"><div><span>${t(base.kind==='current'?'按你的位置排序':'按所选区域中心排序',base.kind==='current'?'Sorted from your location':'Sorted from the selected area center')}</span><strong>${base.kind==='current'?t('当前位置','Your location'):esc(base.name)}</strong></div><button class="tertiary" data-locate>${t('重新定位','Locate me')}</button></div><label class="printer-area-label">${t('纽约区域','New York area')}<select data-printer-area>${areas.map(a=>`<option value="${a.id}" ${base.id===a.id?'selected':''}>${a.name}</option>`).join('')}</select></label><input class="printer-search" type="search" aria-label="${t('搜索设备或地址','Search printers or addresses')}" placeholder="${t('搜索设备、区域或地址','Search printer, area or address')}" value="${esc(search)}"><p class="printer-distance-note">${t('距离为直线距离，实际路线以地图导航为准。','Straight-line distance. Follow the map for the actual route.')}</p><div class="printer-cards">${list.map((p,i)=>`<article class="printer-card ${p.id===selectedId?'is-selected':''}"><div class="printer-card-top"><h3>${esc(p.name.replace(/^POPOMO · /,''))}</h3><span class="printer-distance">${p.distance<1?Math.round(p.distance*1000)+' m':p.distance.toFixed(1)+' km'}${i===0?`<small>${t('最近','Nearest')}</small>`:''}</span></div><div class="printer-card-actions">${onSelect?`<button class="${p.id===selectedId?'tertiary':'primary'}" data-select-printer="${p.id}">${t(p.id===selectedId?'已选择':'选择此设备',p.id===selectedId?'Selected':'Choose printer')}</button>`:''}<a class="${onSelect?'secondary':'primary'}" href="${navigationURL(p)}" target="_blank" rel="noopener noreferrer">${t('地图导航','Directions')} ↗</a></div></article>`).join('')||`<p>${t('未找到相关设备，请更换搜索词。','No matching printers. Try another search.')}</p>`}</div>`;root.querySelector('[data-printer-area]').onchange=e=>{base={...areas.find(a=>a.id===e.target.value),kind:'area'};render();};root.querySelector('[data-locate]').onclick=async()=>{const next=await locationPrompt();if(next){base=next;render();}};root.querySelector('.printer-search').oninput=e=>{search=e.target.value;const input=e.target;const start=input.selectionStart;render();const next=root.querySelector('.printer-search');next.focus();try{next.setSelectionRange(start,start);}catch{}};root.querySelectorAll('[data-select-printer]').forEach(b=>b.onclick=()=>{selectedId=b.dataset.selectPrinter;onSelect(getPrinter(selectedId));});}render();}
export async function choosePrinter({selectedId,onSelect,requestLocation=true}={}){if(printers.length===1){onSelect?.(printers[0]);return;}const origin=currentOrigin||(requestLocation?await locationPrompt():null);const d=document.createElement('dialog');d.className='printer-picker';d.setAttribute('aria-labelledby','printer-picker-title');d.innerHTML=`<header><div><p>FIND YOUR PRINT SPOT</p><h2 id="printer-picker-title">${t('选择纽约打印设备','Choose a New York printer')}</h2></div><button aria-label="${t('关闭','Close')}">×</button></header><div class="printer-picker-body"></div>`;document.body.append(d);d.querySelector('header>button').onclick=()=>d.close();d.addEventListener('close',()=>d.remove(),{once:true});mountPrinterList(d.querySelector('.printer-picker-body'),{origin,selectedId,onSelect:p=>{onSelect?.(p);d.close();}});d.showModal();}
